import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  products: [],
  filteredProducts: [],
  categories: [],
  loading: false,
  error: null,
  searchTerm: '',
  selectedCategory: 'all',
  sortBy: 'name',
  sortOrder: 'asc',
};

const productSlice = createSlice({
  name: 'products',
  initialState,
  reducers: {
    setProducts: (state, action) => {
      state.products = action.payload;
      state.filteredProducts = action.payload;
      state.categories = [...new Set(action.payload.map(product => product.category))];
    },
    setLoading: (state, action) => {
      state.loading = action.payload;
    },
    setError: (state, action) => {
      state.error = action.payload;
    },
    setSearchTerm: (state, action) => {
      state.searchTerm = action.payload;
      state.filteredProducts = filterProducts(state.products, action.payload, state.selectedCategory, state.sortBy, state.sortOrder);
    },
    setSelectedCategory: (state, action) => {
      state.selectedCategory = action.payload;
      state.filteredProducts = filterProducts(state.products, state.searchTerm, action.payload, state.sortBy, state.sortOrder);
    },
    setSortBy: (state, action) => {
      state.sortBy = action.payload;
      state.filteredProducts = filterProducts(state.products, state.searchTerm, state.selectedCategory, action.payload, state.sortOrder);
    },
    setSortOrder: (state, action) => {
      state.sortOrder = action.payload;
      state.filteredProducts = filterProducts(state.products, state.searchTerm, state.selectedCategory, state.sortBy, action.payload);
    },
  },
});

const filterProducts = (products, searchTerm, category, sortBy, sortOrder) => {
  let filtered = products;

  // Filter by search term
  if (searchTerm) {
    filtered = filtered.filter(product =>
      product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.description.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }

  // Filter by category
  if (category && category !== 'all') {
    filtered = filtered.filter(product => product.category === category);
  }

  // Sort products
  filtered.sort((a, b) => {
    let aValue = a[sortBy];
    let bValue = b[sortBy];

    if (sortBy === 'price') {
      aValue = parseFloat(aValue);
      bValue = parseFloat(bValue);
    } else {
      aValue = aValue.toString().toLowerCase();
      bValue = bValue.toString().toLowerCase();
    }

    if (sortOrder === 'asc') {
      return aValue > bValue ? 1 : -1;
    } else {
      return aValue < bValue ? 1 : -1;
    }
  });

  return filtered;
};

export const {
  setProducts,
  setLoading,
  setError,
  setSearchTerm,
  setSelectedCategory,
  setSortBy,
  setSortOrder,
} = productSlice.actions;

export default productSlice.reducer; 